return ['domain'=>'ai-visibility-dashboard','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es_ES','project-id-version'=>'AI Visibility Dashboard for Mencoro 1.0.0','pot-creation-date'=>'2026-10-17T11:53:02+00:00','po-revision-date'=>'2026-10-17 12:00+0200','x-generator'=>'WP-CLI 2.12.0','messages'=>['AI Visibility Dashboard for Mencoro'=>'AI Visibility Dashboard for Mencoro','https://trailseo.com/'=>'https://trailseo.com/','See how ChatGPT, Claude, Perplexity and Google AI talk about your brand, right in the WordPress dashboard. Share of Voice, mention rate, sentiment, competitors and the sources AI answers cite, powered by your Mencoro account.'=>'Descubre cómo hablan de tu marca ChatGPT, Claude, Perplexity y Google IA, sin salir del escritorio de WordPress: cuota de voz, tasa de mención, sentimiento, competidores y las fuentes que citan las respuestas de IA, con los datos de tu cuenta de Mencoro.','TrailSEO'=>'TrailSEO','https://trailseo.com'=>'https://trailseo.com','Settings'=>'Ajustes','AI Visibility'=>'Visibilidad en IA','Google AI Overviews'=>'Google AI Overviews','Google AI Mode'=>'Google Modo IA','You are not allowed to change these settings.'=>'No tienes permiso para cambiar estos ajustes.','Settings saved.'=>'Ajustes guardados.','Key saved and working. Now choose the project to show.'=>'Clave guardada y funcionando. Ahora elige el proyecto que quieres ver.','Settings saved. The widget is ready on your Dashboard.'=>'Ajustes guardados. El widget ya está listo en tu Escritorio.','You are not allowed to do this.'=>'No tienes permiso para hacer esto.','See on your Dashboard how ChatGPT, Claude, Perplexity and Google AI mention your brand: Share of Voice, mention rate, sentiment, competitors and the sources they cite. The data comes from your Mencoro project.'=>'Mira en tu Escritorio cómo mencionan tu marca ChatGPT, Claude, Perplexity y Google IA: cuota de voz, tasa de mención, sentimiento, competidores y las fuentes que citan. Los datos salen de tu proyecto de Mencoro.','1. Mencoro API key'=>'1. Clave de la API de Mencoro','API key'=>'Clave de API','Defined in wp-config.php with the MENCORO_API_KEY constant (ends in %s).'=>'Definida en wp-config.php con la constante MENCORO_API_KEY (termina en %s).','Read from the MENCORO_API_KEY environment variable (ends in %s).'=>'Leída de la variable de entorno MENCORO_API_KEY (termina en %s).','A key ending in %s is saved. Leave the field empty to keep it.'=>'Hay guardada una clave que termina en %s. Deja el campo vacío para conservarla.','Remove the saved key'=>'Borrar la clave guardada','Create a key in your %s account, under API keys in the user menu. The "read" capability is enough: the plugin never changes anything in Mencoro.'=>'Crea una clave en tu cuenta de %s, en «API keys» dentro del menú de usuario. Basta con el permiso «read» (lectura): el plugin nunca cambia nada en Mencoro.','Tip: on shared or client sites, define it in wp-config.php instead: define( \'MENCORO_API_KEY\', \'…\' );'=>'Consejo: en webs compartidas o de clientes, mejor defínela en wp-config.php: define( \'MENCORO_API_KEY\', \'…\' );','2. What to show'=>'2. Qué mostrar','Project'=>'Proyecto','Save your API key first to list your projects.'=>'Guarda primero tu clave de API para ver tus proyectos.','This key cannot see any active project yet. Create one in Mencoro and come back.'=>'Esta clave todavía no ve ningún proyecto activo. Crea uno en Mencoro y vuelve.','— Choose a project —'=>'— Elige un proyecto —','AI engines'=>'Motores de IA','Only the engines your project tracks in Mencoro are used. Google classic results and Shopping are left out on purpose.'=>'Solo se usan los motores que tu proyecto sigue en Mencoro. Los resultados clásicos de Google y Shopping se dejan fuera a propósito.','Default period'=>'Periodo por defecto','Last %d day'=>'Último %d día' . "\0" . 'Últimos %d días','Trends compare with the previous period of the same length.'=>'Las tendencias se comparan con el periodo anterior de la misma duración.','Who sees the widget'=>'Quién ve el widget','Administrators'=>'Administradores','Editors and administrators'=>'Editores y administradores','Handy for agencies: let the client\'s editors see their AI visibility without access to the settings or the key.'=>'Útil para agencias: los editores del cliente ven su visibilidad en IA sin acceder a los ajustes ni a la clave.','Save and check connection'=>'Guardar y comprobar la conexión','Privacy'=>'Privacidad','The plugin only talks to %s, with your key and in read-only mode. It sends nothing about your site or your visitors, adds nothing to the front end and loads no external scripts.'=>'El plugin solo se comunica con %s, con tu clave y en modo de solo lectura. No envía nada sobre tu web ni tus visitantes, no añade nada a la parte pública y no carga scripts externos.','Add your Mencoro API key in the settings.'=>'Añade tu clave de API de Mencoro en los ajustes.','Could not reach Mencoro: %s'=>'No se pudo conectar con Mencoro: %s','Mencoro sent a response the plugin could not read.'=>'Mencoro envió una respuesta que el plugin no ha podido leer.','Mencoro rejected the API key. Check that it is complete and has not been revoked.'=>'Mencoro ha rechazado la clave de API. Comprueba que está completa y que no se ha revocado.','This API key cannot read this data. Give it the "read" capability and access to the organization.'=>'Esta clave de API no puede leer estos datos. Dale el permiso «read» y acceso a la organización.','Mencoro could not find this project with this key. Choose the project again in the settings.'=>'Mencoro no encuentra este proyecto con esta clave. Vuelve a elegir el proyecto en los ajustes.','Too many requests to Mencoro. Try again in %d second.'=>'Demasiadas peticiones a Mencoro. Inténtalo de nuevo en %d segundo.' . "\0" . 'Demasiadas peticiones a Mencoro. Inténtalo de nuevo en %d segundos.','Too many requests to Mencoro. Try again in a few minutes.'=>'Demasiadas peticiones a Mencoro. Inténtalo de nuevo en unos minutos.','Mencoro answered with an error (HTTP %d).'=>'Mencoro ha respondido con un error (HTTP %d).','Competitor'=>'Competidor','AI visibility'=>'Visibilidad en IA','Try again'=>'Reintentar','This project does not track any of the AI engines chosen in the settings. Tick other engines in Settings → AI Visibility.'=>'Este proyecto no sigue ninguno de los motores de IA elegidos en los ajustes. Marca otros motores en Ajustes → Visibilidad en IA.','This Mencoro project does not track any AI engine yet (ChatGPT, Claude, Perplexity or Google AI). Add them to its tracked queries to see data here.'=>'Este proyecto de Mencoro todavía no sigue ningún motor de IA (ChatGPT, Claude, Perplexity o Google IA). Añádelos a sus consultas para ver datos aquí.','No AI answers were checked in this period yet. Mencoro checks most queries once a day: come back tomorrow or choose a longer period.'=>'Todavía no se ha comprobado ninguna respuesta de IA en este periodo. Mencoro revisa casi todas las consultas una vez al día: vuelve mañana o elige un periodo más largo.','Mencoro is recalculating part of this period: figures may still change slightly.'=>'Mencoro está recalculando parte de este periodo: las cifras aún pueden cambiar un poco.','How do ChatGPT, Claude, Perplexity and Google AI talk about your brand?'=>'¿Cómo hablan de tu marca ChatGPT, Claude, Perplexity y Google IA?','Connect your Mencoro project to see your Share of Voice, mention rate, sentiment, competitors and the sources AI answers cite, right here.'=>'Conecta tu proyecto de Mencoro para ver aquí mismo tu cuota de voz, tasa de mención, sentimiento, competidores y las fuentes que citan las respuestas de IA.','Connect Mencoro'=>'Conectar Mencoro','Ask an administrator to connect it in Settings → AI Visibility.'=>'Pide a un administrador que lo conecte en Ajustes → Visibilidad en IA.','Period'=>'Periodo','%d d'=>'%d d','Share of Voice'=>'Cuota de voz','Your share of the brand mentions in AI answers, against the competitors you track.'=>'Tu parte de las menciones de marca en las respuestas de IA, frente a los competidores que sigues.','Mention rate'=>'Tasa de mención','Share of AI checks where your brand appears. %1$d of %2$d tracked queries mention you.'=>'Porcentaje de comprobaciones de IA en las que aparece tu marca. Te mencionan en %1$d de %2$d consultas seguidas.','Average position'=>'Posición media','Where your brand appears inside the answer, on average. Lower is better.'=>'En qué lugar de la respuesta aparece tu marca, de media. Cuanto más bajo, mejor.','Positivity'=>'Positividad','Tone of the mentions, from 0 (negative) to 100 (positive).'=>'Tono de las menciones, de 0 (negativo) a 100 (positivo).','no previous period'=>'sin periodo anterior','pp'=>'pp','no change'=>'sin cambios','Improved by %s against the previous period'=>'Mejora de %s respecto al periodo anterior','Worse by %s against the previous period'=>'Empeora %s respecto al periodo anterior','Share of Voice over time'=>'Evolución de la cuota de voz','Not enough days with data to draw a trend yet.'=>'Todavía no hay suficientes días con datos para dibujar la evolución.','Share of Voice went from %1$s to %2$s in this period, with a high of %3$s.'=>'La cuota de voz pasó de %1$s a %2$s en este periodo, con un máximo de %3$s.','You and your competitors'=>'Tú y tus competidores','you'=>'tú','Positive'=>'Positivo','Neutral'=>'Neutro','Negative'=>'Negativo','Tone of the mentions'=>'Tono de las menciones','Sources the AI answers cite'=>'Fuentes que citan las respuestas de IA','No cited sources in this period.'=>'No hay fuentes citadas en este periodo.','your site'=>'tu web','%s citation'=>'%s cita' . "\0" . '%s citas','Your site is not among the most cited sources. These are the sites the AI trusts on your topics: getting mentioned on them is often the fastest way in.'=>'Tu web no está entre las fuentes más citadas. Estas son las webs en las que confía la IA para tus temas: conseguir que te mencionen en ellas suele ser el camino más rápido.','Queries that moved most'=>'Consultas que más se han movido','Gaining'=>'Suben','Losing'=>'Bajan','None in this period.'=>'Ninguna en este periodo.','What do these figures mean?'=>'¿Qué significan estas cifras?','Your share of the brand mentions in AI answers, against the competitors you track in Mencoro. Higher is better.'=>'Tu parte de las menciones de marca en las respuestas de IA, frente a los competidores que sigues en Mencoro. Cuanto más alta, mejor.','Out of every AI answer checked, how many mention your brand. Higher is better.'=>'De todas las respuestas de IA comprobadas, cuántas mencionan tu marca. Cuanto más alta, mejor.','Where your brand appears inside the answer when it is mentioned. 1 means first. Lower is better.'=>'En qué lugar de la respuesta aparece tu marca cuando te mencionan. 1 es la primera. Cuanto más bajo, mejor.','Tone of the mentions, from 0 (all negative) to 100 (all positive).'=>'Tono de las menciones, de 0 (todas negativas) a 100 (todas positivas).','Percentage points: the change of a percentage against the previous period of the same length.'=>'Puntos porcentuales: cuánto cambia un porcentaje respecto al periodo anterior de la misma duración.','Data from %1$s · updated %2$s ago'=>'Datos de %1$s · actualizado hace %2$s','Refresh'=>'Actualizar']];